SELECT p.id, p.user_id, u.username, u.avatar AS user_avatar, p.category_id, c.name AS category_name, p.title, p.description, p.price, p.original_price, p.`condition`, p.trade_type, p.status, p.view_count, p.want_count, p.favorite_count, p.review_count, p.rating, p.stock, p.version, p.audit_remark, p.audit_time, p.auditor_id, p.create_time, p.update_time FROM product p LEFT JOIN base_user u ON p.user_id = u.id LEFT JOIN category c ON p.category_id = c.id
AND p.user_id = #{userId}
AND p.category_id = #{categoryId}
AND p.title LIKE concat('%', #{title}, '%')
AND p.status = #{status}
AND p.`condition` = #{condition}
AND p.trade_type = #{tradeType}
AND p.price >= #{minPrice}
AND p.price <= #{maxPrice}
ORDER BY p.create_time DESC
LIMIT #{current}, #{size}

SELECT COUNT(*)
FROM product p


        AND p.user_id = #{userId}


        AND p.category_id = #{categoryId}


        AND p.title LIKE concat('%', #{title}, '%')


        AND p.status = #{status}


        AND p.`condition` = #{condition}


        AND p.trade_type = #{tradeType}


        AND p.price >= #{minPrice}


        AND p.price <= #{maxPrice}
